// Host verification: before a game is listed, the lobby connects to the host's TCP port and asks it to prove it
// knows the game's token. Only the PC at that address running the host's game can answer, so nobody can list
// someone else's address (or an address nobody listens on).
//
// Protocol (all ASCII; HMAC keys are the bytes of the hex strings):
//   token  64 lowercase hex chars, generated by the host, sent in the registration body (HTTPS)
//   ckey   hex(HMAC-SHA256(key = token, msg = "H7LOBBY challenge key"))   (the responder never holds the token)
//   lobby  -> host  "H7LOBBY 1 " + nonce + "\n"   nonce: 32 lowercase hex chars (43 bytes)
//   host   -> lobby hex(HMAC-SHA256(key = ckey, msg = nonce)) + "\n"   (65 bytes), then either side closes
import { connect } from "cloudflare:sockets";

export const CHALLENGE_KEY_LABEL = "H7LOBBY challenge key";
export const VERIFY_TIMEOUT_MS = 3000;
const REPLY_BYTES = 65;

const enc = new TextEncoder();
const hex = (buf: ArrayBuffer | Uint8Array) =>
  Array.from(buf instanceof Uint8Array ? buf : new Uint8Array(buf), (b) => b.toString(16).padStart(2, "0")).join("");

export async function hmacHex(key: string, msg: string): Promise<string> {
  const k = await crypto.subtle.importKey("raw", enc.encode(key), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return hex(await crypto.subtle.sign("HMAC", k, enc.encode(msg)));
}

export const deriveChallengeKey = (token: string) => hmacHex(token, CHALLENGE_KEY_LABEL);
export const expectedResponse = (ckey: string, nonce: string) => hmacHex(ckey, nonce);
export const newNonce = () => hex(crypto.getRandomValues(new Uint8Array(16)));
export const challengeLine = (nonce: string) => `H7LOBBY 1 ${nonce}\n`;

export function timingSafeEqualStr(a: string, b: string): boolean {
  const x = enc.encode(a), y = enc.encode(b);
  if (x.length !== y.length) return false;
  return crypto.subtle.timingSafeEqual(x, y);
}

export interface VerifyResult {
  ok: boolean;
  reason?: "timeout" | "connection refused" | "wrong answer" | "closed early";
}

export async function verifyHost(ip: string, port: number, ckey: string, timeoutMs = VERIFY_TIMEOUT_MS): Promise<VerifyResult> {
  const nonce = newNonce();
  const expected = (await expectedResponse(ckey, nonce)) + "\n";
  let socket: ReturnType<typeof connect> | undefined;
  let timer: number | null = null;
  const timeout = new Promise<VerifyResult>((resolve) => { timer = setTimeout(() => resolve({ ok: false, reason: "timeout" }), timeoutMs); });
  const exchange = (async (): Promise<VerifyResult> => {
    try {
      socket = connect({ hostname: ip, port });
      await socket.opened;
    } catch {
      return { ok: false, reason: "connection refused" };
    }
    try {
      const writer = socket.writable.getWriter();
      await writer.write(enc.encode(challengeLine(nonce)));
      writer.releaseLock();
      const reader = socket.readable.getReader();
      const got = new Uint8Array(REPLY_BYTES);
      let n = 0;
      while (n < REPLY_BYTES) {
        const { value, done } = await reader.read();
        if (done) break;
        const take = Math.min(value.length, REPLY_BYTES - n);
        got.set(value.subarray(0, take), n);
        n += take;
      }
      if (n < REPLY_BYTES) return { ok: false, reason: "closed early" };
      return timingSafeEqualStr(new TextDecoder().decode(got), expected) ? { ok: true } : { ok: false, reason: "wrong answer" };
    } catch {
      return { ok: false, reason: "closed early" };
    }
  })();
  try {
    return await Promise.race([exchange, timeout]);
  } finally {
    clearTimeout(timer);
    socket?.close().catch(() => {});
  }
}
